window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d20c03e0fed6f14c"]={"versions": [{"id": "FIG-d20c03e0fed6f14c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Metamodellierungsdiagramm im UML-Paketstil. Es veranschaulicht die Korrespondenz zwischen der vierstufigen AUTOSAR-Modellierungshierarchie (M1 bis M3) auf der linken Seite und den XML-Artefakten auf der rechten Seite, vermittelt über Transformationsregeln („model persistence rules for XML“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptstränge über drei Ebenen:</p>\n<p class=\"fig-p\">Linke Seite (Modellebene):</p>\n<ul class=\"fig-list\"><li><strong>Ebene M3 (AUTOSAR Meta-Metamodel)</strong>: Beinhaltet das Paket <code>UML2.0</code> sowie das Profil-Paket <code>«profile» AUTOSAR Template Profile</code>, welches <code>UML2.0</code> importiert (<code>«import»</code>). Begleitender Notizblock listet typische M3-Konzepte: <code>Class</code>, <code>Property</code>, <code>Association</code>, <code>Tagged Value</code>, <code>«InstanceRef»</code>.\n</li><li><strong>Ebene M2 (AUTOSAR Metamodel)</strong>: Beinhaltet das Paket <code>AUTOSAR Templates</code>. Es instanziiert <code>UML2.0</code> (<code>«instanceOf»</code>) und wendet das Profil an (<code>«apply»</code>). Begleitender Notizblock verweist auf M2-Konzepte: <code>ECU</code>, <code>PortPrototype</code>, <code>AtomicSoftwareComponentType</code>.\n</li><li><strong>Ebene M1 (AUTOSAR Model)</strong>: Beinhaltet das Paket <code>AUTOSAR User Models</code>, das eine Instanz von <code>AUTOSAR Templates</code> darstellt (<code>«instanceOf»</code>). Begleitender Notizblock nennt M1-Beispiele: <code>CompositionType &quot;WindshieldWiper&quot;</code>.\n</li></ul>\n<p class=\"fig-p\">Rechte Seite (XML-Ebene):</p>\n<ul class=\"fig-list\"><li><strong>W3C XML Schema specification</strong>: Das Meta-Schema auf M3-Ebene.\n</li><li><strong>AUTOSAR XML schema</strong>: Schemadatei (<code>&lt;xsd:schema xmlns:AR=&quot;http://autosar.org&quot; xmlns:xsd=&quot;http://www.w3.org/2001/XMLSchema&quot; targetNamespace=&quot;http://autosar.org&quot; elementFormDefault=&quot;qualified&quot; attributeFormDefault=&quot;unqualified&quot;&gt; ... &lt;/xsd:schema&gt;</code>), instanziiert die W3C XML Schema Spezifikation (<code>«instanceOf»</code>).\n</li><li><strong>XML description</strong>: Konkrete XML-Instanzdatei (<code>&lt;... xmlns=&quot;http://autosar.org&quot; xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot; xsi:schemaLocation=&quot;http://autosar.org autosar.xsd&quot;&gt; ... &lt;/...&gt;</code>), instanziiert das <code>AUTOSAR XML schema</code> (<code>«instanceOf»</code>).\n</li></ul>\n<p class=\"fig-p\">Verbindendes Element:</p>\n<ul class=\"fig-list\"><li>Ein blauer Richtungspfeil beschriftet mit <code>model persistence rules for XML</code> transformiert bzw. bildet das Paket <code>AUTOSAR Templates</code> (M2) direkt auf das <code>AUTOSAR XML schema</code> ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsmodell ohne zeitlichen Sequenzablauf. Die Pfeile kennzeichnen Instanziierungsbeziehungen (<code>«instanceOf»</code> von M1 nach M2 und von M2 nach M3 sowie von XML description zu AUTOSAR XML schema und zu W3C XML Schema specification) sowie die Ableitung/Transformation des XML-Schemas aus den M2-Templates gemäß den Persistenzregeln (<code>model persistence rules for XML</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Ableitungsvorschrift zur Generierung des AUTOSAR XML-Schemas aus dem M2-Metamodell (<code>AUTOSAR Templates</code>) und dessen Profilen. Für Entwickler und Tool-Hersteller ist verbindlich vorgegeben, dass Anwendermodelle (M1) als XML-Beschreibungen serialisiert werden, die zwingend gegen das aus M2 generierte <code>AUTOSAR XML schema</code> validieren müssen.</p>"}, {"id": "FIG-2329ba1cd1420c60", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Metamodellierungsdiagramm im UML-Paketstil. Es veranschaulicht die Korrespondenz zwischen der vierstufigen AUTOSAR-Modellierungshierarchie (M1 bis M3) auf der linken Seite und den XML-Artefakten auf der rechten Seite, vermittelt über Transformationsregeln („model persistence rules for XML“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptstränge über drei Ebenen:</p>\n<p class=\"fig-p\">Linke Seite (Modellebene):</p>\n<ul class=\"fig-list\"><li><strong>Ebene M3 (AUTOSAR Meta-Metamodel)</strong>: Beinhaltet das Paket <code>UML2.0</code> sowie das Profil-Paket <code>«profile» AUTOSAR Template Profile</code>, welches <code>UML2.0</code> importiert (<code>«import»</code>). Begleitender Notizblock listet typische M3-Konzepte: <code>Class</code>, <code>Property</code>, <code>Association</code>, <code>Tagged Value</code>, <code>«InstanceRef»</code>.\n</li><li><strong>Ebene M2 (AUTOSAR Metamodel)</strong>: Beinhaltet das Paket <code>AUTOSAR Templates</code>. Es instanziiert <code>UML2.0</code> (<code>«instanceOf»</code>) und wendet das Profil an (<code>«apply»</code>). Begleitender Notizblock verweist auf M2-Konzepte: <code>ECU</code>, <code>PortPrototype</code>, <code>AtomicSoftwareComponentType</code>.\n</li><li><strong>Ebene M1 (AUTOSAR Model)</strong>: Beinhaltet das Paket <code>AUTOSAR User Models</code>, das eine Instanz von <code>AUTOSAR Templates</code> darstellt (<code>«instanceOf»</code>). Begleitender Notizblock nennt M1-Beispiele: <code>CompositionType &quot;WindshieldWiper&quot;</code>.\n</li></ul>\n<p class=\"fig-p\">Rechte Seite (XML-Ebene):</p>\n<ul class=\"fig-list\"><li><strong>W3C XML Schema specification</strong>: Das Meta-Schema auf M3-Ebene.\n</li><li><strong>AUTOSAR XML schema</strong>: Schemadatei (<code>&lt;xsd:schema xmlns:AR=&quot;http://autosar.org&quot; xmlns:xsd=&quot;http://www.w3.org/2001/XMLSchema&quot; targetNamespace=&quot;http://autosar.org&quot; elementFormDefault=&quot;qualified&quot; attributeFormDefault=&quot;unqualified&quot;&gt; ... &lt;/xsd:schema&gt;</code>), instanziiert die W3C XML Schema Spezifikation (<code>«instanceOf»</code>).\n</li><li><strong>XML description</strong>: Konkrete XML-Instanzdatei (<code>&lt;... xmlns=&quot;http://autosar.org&quot; xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot; xsi:schemaLocation=&quot;http://autosar.org autosar.xsd&quot;&gt; ... &lt;/...&gt;</code>), instanziiert das <code>AUTOSAR XML schema</code> (<code>«instanceOf»</code>).\n</li></ul>\n<p class=\"fig-p\">Verbindendes Element:</p>\n<ul class=\"fig-list\"><li>Ein blauer Richtungspfeil beschriftet mit <code>model persistence rules for XML</code> transformiert bzw. bildet das Paket <code>AUTOSAR Templates</code> (M2) direkt auf das <code>AUTOSAR XML schema</code> ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsmodell ohne zeitlichen Sequenzablauf. Die Pfeile kennzeichnen Instanziierungsbeziehungen (<code>«instanceOf»</code> von M1 nach M2 und von M2 nach M3 sowie von XML description zu AUTOSAR XML schema und zu W3C XML Schema specification) sowie die Ableitung/Transformation des XML-Schemas aus den M2-Templates gemäß den Persistenzregeln (<code>model persistence rules for XML</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normative Ableitungsvorschrift zur Generierung des AUTOSAR XML-Schemas aus dem M2-Metamodell (<code>AUTOSAR Templates</code>) und dessen Profilen. Für Entwickler und Tool-Hersteller ist verbindlich vorgegeben, dass Anwendermodelle (M1) als XML-Beschreibungen serialisiert werden, die zwingend gegen das aus M2 generierte <code>AUTOSAR XML schema</code> validieren müssen.</p>"}], "trans": [{"from": "FIG-d20c03e0fed6f14c", "to": "FIG-2329ba1cd1420c60", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
